// SR-4: verify HMAC(secret, timestamp + '.' + rawBody), 5-minute window, constant-time compare.
// The secret comes from the container env, so it never appears in this exported JSON.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}
const ts = headers['x-lendloop-timestamp'];
const sig = String(headers['x-lendloop-signature'] || '').toLowerCase();
const eventId = headers['x-lendloop-event-id'];
const secret = $env.LENDLOOP_N8N_HMAC_SECRET;
const reject = (reason) => [{ json: { valid: false, reason } }];

if (!secret) return reject('not_configured');
if (!ts || !sig || !eventId || !/^\d{1,12}$/.test(ts)) return reject('missing_headers');
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject('expired');
const expected = Buffer.from(crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex'));
const given = Buffer.from(sig);
if (expected.length !== given.length || !crypto.timingSafeEqual(expected, given)) return reject('bad_signature');

let event;
try { event = JSON.parse(raw); } catch { return reject('invalid_json'); }
if (event.eventId !== eventId) return reject('event_id_mismatch');

// RR-2: dedupe on eventId. Ids are remembered only after a successful send (see 'Remember event').
const seen = $getWorkflowStaticData('global').seen || {};
return [{ json: { valid: true, duplicate: Boolean(seen[eventId]), event } }];

const e = $json.event;
const when = e.dates.start === e.dates.end ? e.dates.start : `${e.dates.start} to ${e.dates.end}`;
const text = e.type === 'request.created'
  ? `Hi ${e.recipient.firstName}, a neighbor asked to borrow your ${e.tool.name} (${when}). Open LendLoop to approve or decline.`
  : `Hi ${e.recipient.firstName}, the request for your ${e.tool.name} (${when}) was cancelled by the borrower.`;
return { json: { eventId: e.eventId, type: e.type, to: e.recipient.email, subject: `LendLoop: ${e.tool.name}`, text } };

const e = $json.event;
const when = e.dates.start === e.dates.end ? e.dates.start : `${e.dates.start} to ${e.dates.end}`;
const lines = {
  'request.approved': `Good news ${e.recipient.firstName}: your request for the ${e.tool.name} (${when}) was approved.`,
  'request.declined': `Hi ${e.recipient.firstName}, your request for the ${e.tool.name} (${when}) was declined.`,
  'loan.returned': `Thanks ${e.recipient.firstName}! The ${e.tool.name} has been marked as returned.`,
};
return { json: { eventId: e.eventId, type: e.type, to: e.recipient.email, subject: `LendLoop: ${e.tool.name}`, text: lines[e.type] } };

// Mock channel: logs the message instead of emailing. Swap for an Email/Slack node with a credential in production.
if ($env.LENDLOOP_FORCE_FAIL === 'true') {
  throw new Error('Forced failure (LENDLOOP_FORCE_FAIL=true)');
}
// Log a masked address only (SR-9).
const masked = $json.to.replace(/^(.).*(@.*)$/, '$1***$2');
console.log(`[lendloop] ${$json.type} -> ${masked}: ${$json.subject}`);
return { json: { eventId: $json.eventId, delivered: true, channel: 'mock-log' } };

// Record delivered eventIds so a redelivery from Convex is answered as a duplicate. Keep 24h.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const [id, t] of Object.entries(store.seen)) if (now - t > 86400000) delete store.seen[id];
for (const item of $input.all()) store.seen[item.json.eventId] = now;
return [{ json: { status: 'sent' } }];
